const BASE_PRICE_BY_TYPE: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
};

const FIRST_INSURANCE_SURCHARGE = 1.1;
const CONTRACT_FEE = 5;

// Math.round only clears the float artifact in 100 × 1.1 = 110.00000000000001;
// no test yet lands on a half-way value, so the rounding *direction* stays
// unspecified until the "rounds in MHPCO's favor" test pins it.
const quotePremium = (item: Item): number =>
  Math.round(BASE_PRICE_BY_TYPE[item.type] * FIRST_INSURANCE_SURCHARGE) + CONTRACT_FEE;
